description:
Each function receives an array as a pointer and a count. Write them **without square brackets**: move pointers and use `*` instead.

```cpp
int sum(const int* values, int count);
void reverseInPlace(int* values, int count);
int countAbove(const int* values, int count, int limit);
```

- **sum** adds up the `count` values.
- **reverseInPlace** reverses the order of the values in the caller's array.
- **countAbove** counts the values greater than `limit`.

A count of 0 is allowed in all three.

starter.solution.cpp:
int sum(const int* values, int count) { return 0; }
void reverseInPlace(int* values, int count) {}
int countAbove(const int* values, int count, int limit) { return 0; }

solution.solution.cpp:
int sum(const int* values, int count)
{
    int total{ 0 };
    for (const int* p{ values }; p != values + count; ++p) total += *p;
    return total;
}

void reverseInPlace(int* values, int count)
{
    int* left{ values };
    int* right{ values + count };
    while (left < right)
    {
        --right;
        if (left == right) break;
        const int t{ *left };
        *left = *right;
        *right = t;
        ++left;
    }
}

int countAbove(const int* values, int count, int limit)
{
    int n{ 0 };
    for (const int* p{ values }; p != values + count; ++p)
        if (*p > limit) ++n;
    return n;
}

unitTests:
TEST("sum") {
    const int a[]{ 4, -2, 10, 3 };
    CHECK_EQ(sum(a, 4), 15);
    CHECK_EQ(sum(a + 1, 2), 8);
    CHECK_EQ(sum(a, 0), 0);
}
TEST("reverse in place") {
    int a[]{ 1, 2, 3, 4, 5 };
    reverseInPlace(a, 5);
    CHECK_EQ(a[0], 5); CHECK_EQ(a[1], 4); CHECK_EQ(a[2], 3); CHECK_EQ(a[3], 2); CHECK_EQ(a[4], 1);
    int b[]{ 7, 8 };
    reverseInPlace(b, 2);
    CHECK_EQ(b[0], 8); CHECK_EQ(b[1], 7);
    int c[]{ 9, 1, 2, 3 };
    reverseInPlace(c + 1, 3);
    CHECK_EQ(c[0], 9); CHECK_EQ(c[1], 3); CHECK_EQ(c[3], 1);
    reverseInPlace(c, 0);
    CHECK_EQ(c[0], 9);
}
TEST("count above") {
    const int a[]{ 5, 12, 7, 30, 12 };
    CHECK_EQ(countAbove(a, 5, 10), 3);
    CHECK_EQ(countAbove(a, 5, 12), 1);
    CHECK_EQ(countAbove(a, 0, 0), 0);
}

